 "content": "def transform(grid):
    """Replace each nonzero cell by a 3x3 copy of the input's zero mask."""
    h = len(grid)
    w = len(grid[0]) if h else 0
    out = [[0 for _ in range(w * 3)] for _ in range(h * 3)]
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color != 0:
                for dr in range(h):
                    for dc in range(w):
                        if grid[dr][dc] == 0:
                            out[r * h + dr][c * w + dc] = color
    return out
